  const style=document.createElement('style');
  style.textContent=`#runnymede-live{margin:28px 0 36px;scroll-margin-top:92px}.rm-k{font-size:11px;font-weight:850;letter-spacing:.07em;text-transform:uppercase;color:#687078;margin-bottom:7px}.rm-title{margin:0 0 9px;font-size:27px;line-height:1.2}.rm-lead{margin:0 0 18px;line-height:1.64;color:#3f4850}.rm-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.rm-card{background:#fff;border:1px solid rgba(23,32,42,.12);border-radius:18px;padding:19px;box-shadow:0 8px 24px rgba(23,32,42,.055)}.rm-card.wide{grid-column:1/-1}.rm-card h3{margin:0 0 9px;font-size:20px;line-height:1.3}.rm-card p,.rm-card li{line-height:1.58}.rm-card p{margin:0 0 10px}.rm-card ul,.rm-card ol{margin:7px 0 10px;padding-left:20px}.rm-route,.rm-note{border-radius:12px;padding:11px 13px;margin:12px 0;font-size:14px;line-height:1.52}.rm-route{background:#f4f2ec}.rm-note{background:#fff6dc;border:1px solid #eadba9}.rm-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.rm-actions a{display:inline-block;padding:9px 12px;border-radius:999px;text-decoration:none;font-size:13px;font-weight:750;border:1px solid rgba(23,32,42,.16);color:#17202a;background:#fff}.rm-actions a:first-child{background:#17202a;color:#fff;border-color:#17202a}@media(max-width:720px){.rm-grid{grid-template-columns:1fr}.rm-card.wide{grid-column:auto}.rm-title{font-size:23px}.rm-card{padding:16px}}`;
  document.head.appendChild(style);
